function prepareDiscourseSignature(raw, headers) {
  const signature = headers?.["x-discourse-event-signature"];
  if (
    !raw ||
    raw.length > 65536 ||
    typeof signature !== "string" ||
    !/^sha256=[a-f0-9]{64}$/.test(signature) ||
    !/^application\/json(?:\s*;|$)/i.test(headers["content-type"] ?? "")
  ) {
    return { raw: "", signature: "" };
  }
  const text = raw.toString("utf8");
  if (!Buffer.from(text, "utf8").equals(raw)) return { raw: "", signature: "" };
  return {
    raw: text,
    signature: signature.slice(7),
    event: headers["x-discourse-event"],
    kind: headers["x-discourse-event-type"],
    forum: headers["x-discourse-instance"],
  };
}

let bytes;
try {
  bytes = await helpers.getBinaryDataBuffer($itemIndex, "data");
} catch {}
return { json: prepareDiscourseSignature(bytes, $json.headers) };

function normalizedWorkEmail(value) {
  const email = typeof value === "string" ? value.trim().toLowerCase() : "";
  return /^[a-z0-9._%+-]+@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(email)
    ? email
    : "";
}

function admitDiscourseSignup(prepared, computed, settings) {
  if (!prepared.signature || typeof computed !== "string" || !/^[a-f0-9]{64}$/.test(computed))
    return { status: 401 };
  let difference = 0;
  for (let i = 0; i < 64; i++)
    difference |= prepared.signature.charCodeAt(i) ^ computed.charCodeAt(i);
  if (difference) return { status: 401 };
  const forum = typeof settings.forum === "string" ? settings.forum.replace(/\/$/, "") : "";
  if (
    !/^https:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}(?:\/[a-z0-9._-]+)*$/i.test(
      forum,
    ) ||
    prepared.forum?.replace(/\/$/, "") !== forum ||
    prepared.kind !== "user" ||
    prepared.event !== "user_created"
  )
    return { status: 200 };
  let user;
  try {
    user = JSON.parse(prepared.raw)?.user;
  } catch {
    return { status: 400 };
  }
  const email = normalizedWorkEmail(user?.email);
  if (!email || !Number.isSafeInteger(user?.id) || user.id < 1 || user.staged === true)
    return { status: 200 };
  const domain = email.split("@")[1];
  if (/^(gmail|yahoo|hotmail|proton)(\.|mail\.)/i.test(domain)) return { status: 200 };
  if (!/^C[A-Z0-9]{6,}$/.test(settings.channel) && !/^G[A-Z0-9]{6,}$/.test(settings.channel))
    return { status: 200 };
  if (
    !Number.isInteger(settings.minEmployees) ||
    settings.minEmployees < 1 ||
    !Number.isInteger(settings.maxGlobalRank) ||
    settings.maxGlobalRank < 1
  )
    return { status: 200 };
  return {
    status: 200,
    signup: {
      key: forum + ":" + user.id,
      email,
      domain,
      channel: settings.channel,
      minEmployees: settings.minEmployees,
      maxGlobalRank: settings.maxGlobalRank,
    },
  };
}

const settings = {
  forum: "",
  channel: "",
  minEmployees: 30,
  maxGlobalRank: 100000,
};
return {
  json: admitDiscourseSignup(
    $("Read the original request bytes").first().json,
    $json.computed,
    settings,
  ),
};

function normalizedWorkEmail(value) {
  const email = typeof value === "string" ? value.trim().toLowerCase() : "";
  return /^[a-z0-9._%+-]+@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(email)
    ? email
    : "";
}

function cleanSlackText(value, limit) {
  return typeof value === "string"
    ? value
        .replace(/[\u0000-\u001f\u007f]/g, " ")
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, limit)
    : "";
}

function qualifiedCompany(response, signup) {
  if (response?.statusCode === 404 || response?.statusCode === 451) return null;
  if (response?.statusCode !== 200) throw Error("Hunter enrichment unavailable");
  const { person, company } = response.body?.data ?? {};
  if (
    normalizedWorkEmail(person?.email) !== signup.email ||
    person?.employment?.domain?.toLowerCase() !== signup.domain ||
    company?.domain?.toLowerCase() !== signup.domain
  )
    return null;
  const count = company.metrics?.employeesCount;
  if (!Number.isInteger(count) || count < signup.minEmployees) return null;
  const name = cleanSlackText(person.name?.fullName, 180);
  const employer = cleanSlackText(person.employment?.name ?? company.name, 180);
  if (!name || !employer) return null;
  const title = cleanSlackText(person.employment?.title, 160);
  const industry = cleanSlackText(company.category?.industry, 160);
  const handle = typeof person.linkedin?.handle === "string" ? person.linkedin.handle : "";
  const linkedIn = /^(?:in|pub)\/[a-z0-9_-]+(?:\/[a-z0-9_-]+){0,3}\/?$/i.test(handle)
    ? "https://www.linkedin.com/" + handle
    : null;
  return { ...signup, count, name, employer, title, industry, linkedIn };
}

function rankingWindow(at) {
  const now = new Date(at);
  if (!Number.isFinite(now.getTime())) throw Error("Invalid execution time");
  const period = (delta) =>
    new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + delta, 1))
      .toISOString()
      .slice(0, 7);
  return { start: period(-3), end: period(-1) };
}

const company = qualifiedCompany(
  $input.first().json,
  $("Select the authorized business email").first().json,
);
return company ? [{ json: { company, period: rankingWindow(Date.now()) } }] : [];

function slackDiscourseNotice(response, qualified, period) {
  if (response?.statusCode !== 200) throw Error("Similarweb rank unavailable");
  const payload = response.body;
  if (
    payload?.meta?.status?.toLowerCase() !== "success" ||
    payload.meta.request?.domain?.toLowerCase() !== qualified.domain ||
    !["ww", "world"].includes(payload.meta.request?.country?.toLowerCase())
  )
    return null;
  const rows = Array.isArray(payload.data) ? payload.data : [];
  const byDate = new Map();
  for (const row of rows) {
    if (typeof row?.date !== "string" || !/^\d{4}-\d{2}-01$/.test(row.date)) return null;
    const month = row.date.slice(0, 7);
    if (month < period.start || month > period.end || byDate.has(month)) return null;
    byDate.set(month, row.country_rank);
  }
  const month = [...byDate.keys()].sort().at(-1);
  const rank = byDate.get(month);
  if (!Number.isInteger(rank) || rank < 1 || rank > qualified.maxGlobalRank) return null;
  const lines = [
    "Qualified Discourse signup",
    qualified.name + (qualified.title ? " · " + qualified.title : ""),
    qualified.employer + (qualified.industry ? " · " + qualified.industry : ""),
    "Work email: " + qualified.email,
    "Employees: " + qualified.count + " · Similarweb worldwide rank: " + rank + " (" + month + ")",
  ];
  const blocks = [{ type: "section", text: { type: "plain_text", text: lines.join("\n") } }];
  if (qualified.linkedIn)
    blocks.push({
      type: "actions",
      elements: [
        {
          type: "button",
          action_id: "open_linkedin",
          text: { type: "plain_text", text: "Open LinkedIn profile" },
          url: qualified.linkedIn,
        },
      ],
    });
  return {
    key: qualified.key,
    request: {
      channel: qualified.channel,
      text: "Qualified Discourse signup",
      blocks,
      unfurl_links: false,
      unfurl_media: false,
    },
  };
}

const { company, period } = $("Check exact matching and employee count").first().json;
const notice = slackDiscourseNotice($input.first().json, company, period);
return notice ? [{ json: notice }] : [];

const response = $input.first().json;
const notice = $("Check the ranking and prepare the Slack notice").first().json;
const channel = response.channel;
if (
  response.ok !== true ||
  channel?.id !== notice.request.channel ||
  channel.is_private !== true ||
  (channel.is_channel !== true && channel.is_group !== true) ||
  channel.is_archived !== false ||
  channel.is_shared !== false ||
  channel.is_ext_shared !== false ||
  channel.is_pending_ext_shared !== false
)
  return [];
return [{ json: notice }];

if (
  $json.ok !== true ||
  $json.channel !==
    $("Check the ranking and prepare the Slack notice").first().json.request.channel ||
  !/^\d+\.\d+$/.test($json.ts)
) {
  throw Error("Inspect the destination Slack channel before retrying");
}
return { json: { status: "posted", channel: $json.channel, ts: $json.ts } };
